// Only rules generated by this editor are parsed back into its limited form.
// Arbitrary Sieve remains editable in the full mail-rules screen.
const PREFIX = '# GXWebMail vacation v1\nrequire "vacation";\nvacation :subject ';
const MANAGED = /^# GXWebMail vacation v1\nrequire "vacation";\nvacation :subject "((?:\\.|[^"\\])*)" text:\n([\s\S]*)\n\.\n;$/u;

export type AwayDraft = { subject: string; message: string; enabled: boolean };
export type AwayRuleInput = { id: string | null; name: string; kind: "filter" | "vacation" | "advanced"; source: string; enabled: boolean };

export function emptyAdvancedRules(state: { mode: string; source: string; enabled: boolean; rules: readonly unknown[] }): boolean {
  return state.mode === "advanced" && state.source === "" && !state.enabled && state.rules.length === 0;
}

export function replaceManagedAwayRule(
  rules: readonly AwayRuleInput[], managedId: string | null, source: string, enabled: boolean, newName: string,
): AwayRuleInput[] {
  if (managedId !== null && !rules.some((rule) => rule.id === managedId && rule.kind === "vacation")) throw new Error("invalid_request");
  const retained = rules.map((rule) => rule.id === managedId && managedId !== null
    ? { ...rule, source, enabled } : { ...rule });
  if (managedId === null) retained.push({ id: null, name: newName, kind: "vacation", source, enabled });
  return retained;
}

export function validAwayDraft(draft: AwayDraft): boolean {
  return Boolean(draft.subject.trim() && draft.message.trim()) &&
    [...draft.subject].length <= 120 && new TextEncoder().encode(draft.message).length <= 8192 &&
    !/[\r\n\u0000]/u.test(draft.subject) && !draft.message.includes("\u0000");
}

export function makeAwaySource(draft: AwayDraft): string {
  if (!validAwayDraft(draft)) throw new Error("invalid_request");
  const subject = draft.subject.trim().replaceAll("\\", "\\\\").replaceAll('"', '\\"');
  const lines = draft.message.replace(/\r\n?/gu, "\n").replace(/\n+$/u, "").split("\n");
  const message = lines.map((line) => line.startsWith(".") ? `.${line}` : line).join("\r\n");
  const source = `${PREFIX}"${subject}" text:\r\n${message}\r\n.\r\n;`;
  if (new TextEncoder().encode(source).length > 65_536) throw new Error("invalid_request");
  return source;
}

export function readAwaySource(source: string): Pick<AwayDraft, "subject" | "message"> | null {
  const match = MANAGED.exec(source.replace(/\r\n?/gu, "\n"));
  if (!match) return null;
  const subject = match[1].replace(/\\(.)/gu, "$1");
  const lines = match[2].split("\n");
  if (lines.some((line) => line.startsWith(".") && !line.startsWith(".."))) return null;
  const message = lines.map((line) => line.startsWith("..") ? line.slice(1) : line).join("\n");
  const draft = { subject, message, enabled: false };
  return validAwayDraft(draft) ? { subject, message } : null;
}
